namespace Fanex.Age.UI
{
    using System.Collections;
    using System.Web;
    using System.Web.UI;
    using Fanex.Razorbill.Security.Services;
    using Fanex.Razorbill.Security.Sessions;

    /// <summary>
    /// Base IBC page. All aspx pages should be inherited from TplPage or TplPage2.
    /// </summary>
    public abstract class TplPage : TplBase
    {
        /// <summary>
        /// Root namespace of json data returned.
        /// </summary>
        private const string JsData = "_page";

        /// <summary>
        /// List of values will be rendered to browser as JSON format.
        /// </summary>
        protected JsonData JsonData = new JsonData(10);

        private ISecurityCodeSession _securityCodeSession;

        /// <summary>
        /// Gets the security code session.
        /// </summary>
        /// <value>
        /// The security code session.
        /// </value>
        protected ISecurityCodeSession SecurityCodeSession
        {
            get
            {
                if (null == HttpContext.Current.Session)
                {
                    return null;
                }

                return _securityCodeSession ?? (_securityCodeSession = CookieLessSessionFactory.SecurityCodeSession);
            }
        }

        /// <summary>
        /// Register an object as JSON format. Access object in client site by _page.objName.
        /// </summary>
        /// <param name="name">Name of the object.</param>
        /// <param name="value">Value of the object. It could be a JSONData object.</param>
        public void RegisterJavascriptObject(object name, object value)
        {
            JsonData.Add(name, value);
        }

        /// <summary>
        /// Register an error as JSON format.
        /// </summary>
        /// <param name="errCode"></param>
        /// <param name="errMsg"></param>
        public void RegisterJsonError(int errCode, string errMsg)
        {
            JsonData.Add(JsonError.ErrorCode, errCode);
            JsonData.Add(JsonError.ErrorMsg, errMsg);
        }

        /// <summary>
        /// Register an error as JSON format.
        /// </summary>
        /// <param name="type"> </param>
        /// <param name="errMsg"></param>
        public void RegisterJsonError(ErrorType type, string errMsg)
        {
            JsonData.Add(JsonError.ErrorCode, (int)type);
            JsonData.Add(JsonError.ErrorMsg, errMsg);
        }

        /// <summary>
        /// Render content section of html page.
        /// </summary>
        /// <param name="writer"></param>
        public abstract void RenderContent(HtmlTextWriter writer);

        /// <summary>
        /// Don't override this method in instance class.
        /// </summary>
        /// <param name="writer"></param>
        ///
        ///
        protected override void Render(HtmlTextWriter writer)
        {
            try
            {
                // Hot fix for Opera browser (IIS does sniffing user agent)
                Response.ContentType = "text/html";

                // Check Security Code - New Flow
                string redirectUrl = SecurityCodeChecker.GetRedirectUrl();

                if (redirectUrl != null)
                {
                    Response.Redirect(redirectUrl, true);
                }

                _Parameters = new Hashtable();

                ProcessRequest(ref _Parameters);

                var error = ValidateRequest(Parameters);

                if (null != error)
                {
                    writer.Write(error);
                }
                else
                {
                    if (!IsPostBack)
                    {
                        _View = InvokeData(Parameters);
                    }

                    RenderContent(writer);

                    RenderSecurityContent(writer);
                }

                if (JsonData.Count > 0)
                {
                    WriteJavascriptObjects(writer);
                }
            }
            catch
            {
                throw;
            }
        }

        protected virtual void RenderSecurityContent(HtmlTextWriter writer)
        {
        }

        protected void WriteJavascriptObjects(HtmlTextWriter writer)
        {
            writer.Write("<script type=\"text/javascript\">var ");
            writer.Write(JsData);
            writer.Write(" = ");
            writer.Write(Json.Render(JsonData));
            writer.Write(";");
            writer.Write("</script>");
        }
    }
}